:root {
  --bg-card: #0f172a;
  --bg-header: #1e293b;
  --bg-section: #1a2744;
  --bg-spec: #0f172a;
  --bg-footer: #1e293b;
  --bg-avatar: #3b82f6;
  --bg-badge: #22c55e;
  --bg-time: #0f172a;
  --accent-blue: #60a5fa;
  --accent-gold: #fbbf24;
  --accent-green: #4ade80;
  --text-primary: #f1f5f9;
  --text-secondary: #94a3b8;
  --text-muted: #475569;
  --border-color: #2d3f5e;
  --scope-color: #334155;
  --scope-lens: #3b82f6;
  --divider-line: #2d3f5e;
}

.rental-card {
  width: 460px;
  background: var(--bg-card);
  border-radius: 14px;
  border: 1px solid var(--border-color);
  overflow: hidden;
  font-size: 13px;
}

.card-header {
  background: var(--bg-header);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-color);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.card-icon {
  font-size: 22px;
  line-height: 1;
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.card-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.card-subtitle {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 0;
}

.rental-badge {
  background: var(--bg-badge);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 20px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.scope-info {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 14px;
  background: var(--bg-section);
  border-bottom: 1px solid var(--border-color);
}

.scope-visual {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  margin: 0;
  flex-shrink: 0;
}

.scope-body {
  display: flex;
  align-items: center;
}

.scope-lens {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--scope-lens);
  border: 3px solid var(--accent-blue);
  flex-shrink: 0;
}

.scope-tube {
  width: 56px;
  height: 10px;
  background: var(--scope-color);
  border-radius: 2px;
  border: 1px solid var(--border-color);
}

.scope-eyepiece {
  width: 8px;
  height: 15px;
  background: var(--scope-color);
  border-radius: 0 3px 3px 0;
  border: 1px solid var(--border-color);
}

.scope-model {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-blue);
  letter-spacing: 0.04em;
}

.spec-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 16px;
  flex: 1;
}

.spec-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg-spec);
  border-radius: 5px;
  padding: 4px 7px;
  border: 1px solid var(--border-color);
}

.spec-label {
  font-size: 10px;
  color: var(--text-secondary);
}

.spec-value {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
}

.time-row {
  display: flex;
  align-items: center;
  padding: 10px 14px;
  gap: 10px;
  border-bottom: 1px solid var(--border-color);
}

.time-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  background: var(--bg-time);
  border-radius: 8px;
  padding: 8px 6px;
  border: 1px solid var(--border-color);
}

.time-label {
  font-size: 10px;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.time-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--accent-gold);
  line-height: 1.1;
}

.time-date {
  font-size: 10px;
  color: var(--text-muted);
}

.time-divider {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}

.divider-line {
  width: 1px;
  height: 12px;
  background: var(--divider-line);
}

.divider-icon {
  font-size: 11px;
  color: var(--accent-gold);
  line-height: 1;
}

.card-footer {
  background: var(--bg-footer);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.renter-info {
  display: flex;
  align-items: center;
  gap: 8px;
}

.renter-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--bg-avatar);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.renter-details {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.renter-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.renter-id {
  font-size: 10px;
  color: var(--text-muted);
}

.footer-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.price-label {
  font-size: 10px;
  color: var(--text-secondary);
}

.price-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--accent-green);
}
